/**
 * How Five ginkgo leaves (`itsutsu-icho`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/itsutsu-icho";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"Five scalloped ginkgo leaves look inward along pale curves to a round heart.","ja":"ふくらみのある五枚の銀杏を、白い弧に沿って丸い中心へ向けます。"};

export default construction;
export { construction, description };
